package com.ruoyi.metal.service;
import java.util.*;import java.io.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.math.BigDecimal;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.*;import org.apache.poi.xssf.streaming.SXSSFWorkbook;import org.apache.poi.ss.usermodel.*;import com.ruoyi.metal.catalog.*;import org.slf4j.LoggerFactory;
@Service public class BusinessExportService {
 private final JdbcTemplate jdbc;private final BusinessQueries queries;public BusinessExportService(JdbcTemplate jdbc,BusinessQueries queries){this.jdbc=jdbc;this.queries=queries;}
 private record Column(String key,String label){}
 private static class Writer {final SXSSFWorkbook book;final String title;final Column[] columns;int number=0,row;Sheet sheet;final CellStyle heading;Writer(SXSSFWorkbook b,String title,Column...c){book=b;this.title=title;columns=c;heading=b.createCellStyle();var font=b.createFont();font.setBold(true);heading.setFont(font);next();}void next(){sheet=book.createSheet(title+(number++==0?"":"-"+number));row=0;var head=sheet.createRow(row++);for(int i=0;i<columns.length;i++){head.createCell(i).setCellValue(columns[i].label);head.getCell(i).setCellStyle(heading);sheet.setColumnWidth(i,(columns[i].key.equals("specification")?45:24)*256);}sheet.createFreezePane(0,1);}void add(Map<String,Object> data){if(row>=1048576)next();var r=sheet.createRow(row++);for(int i=0;i<columns.length;i++){Object value=data.get(columns[i].key);String text=value==null?"":value instanceof BigDecimal d?d.toPlainString():value instanceof java.sql.Timestamp t?t.toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")):value.toString();r.createCell(i).setCellValue(text);}}}
 private static Column c(String key,String label){return new Column(key,label);}
 @Transactional(isolation=Isolation.REPEATABLE_READ,rollbackFor=Exception.class)
 public long staff(ListQuery q,OutputStream output)throws IOException{
  var p=queries.staff(q);var book=new SXSSFWorkbook(100);try(book){book.setCompressTempFiles(true);var writer=new Writer(book,"人员",c("user_name","登录账号"),c("phonenumber","手机号"),c("nick_name","姓名"),c("factory_name","所属工厂"),c("roles","角色"),c("status_name","状态"),c("create_time","创建时间"));long count=0;for(int offset=0;;offset+=1000){var args=new ArrayList<>(p.args());args.add(offset);var rows=jdbc.queryForList("SELECT u.user_name,u.phonenumber,u.nick_name,f.factory_name,(SELECT GROUP_CONCAT(r.role_name ORDER BY r.role_sort,r.role_id SEPARATOR '、') FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id WHERE ur.user_id=u.user_id) roles,CASE u.status WHEN '0' THEN '启用' ELSE '停用' END status_name,u.create_time FROM sys_user u LEFT JOIN metal_factory f ON f.factory_id=u.factory_id WHERE "+p.sql()+" ORDER BY u.user_id DESC LIMIT 1000 OFFSET ?",args.toArray());for(var row:rows)writer.add(row);count+=rows.size();if(rows.size()<1000)break;}book.write(output);LoggerFactory.getLogger(getClass()).info("BUSINESS_EXPORT kind=staff count={} factory={}",count,q.getFactoryId());return count;}finally{book.dispose();}
 }
 private static final Map<String,String> TYPES=Map.ofEntries(Map.entry("PRODUCTION_OUT","生产出库"),Map.entry("PRODUCT_OUT","产品出库"),Map.entry("EXCHANGE_OUT","还料出库"),Map.entry("SEMI_OUT","半成品出库"),Map.entry("RAW_IN","原材料入库"),Map.entry("FINISHED_IN","成品入库"),Map.entry("SEMI_IN","半成品入库"),Map.entry("RAW_RETURN","原料还库"),Map.entry("PRODUCT_RETURN","成品退还"),Map.entry("OPENING","期初登记"),Map.entry("ADJUST","库存调整"));
 @Transactional(isolation=Isolation.REPEATABLE_READ,rollbackFor=Exception.class)
 public long orders(OrderListQuery q,OutputStream output)throws IOException{
  var p=queries.orders(q);var book=new SXSSFWorkbook(100);try(book){book.setCompressTempFiles(true);var summary=new Writer(book,"单据汇总",c("order_no","单据编号"),c("work_order_no","生产工单号"),c("factory_name","工厂"),c("order_date","单据日期"),c("warehouse_name","仓库"),c("type_name","类型"),c("operator_name","经办人"),c("recipient_name","领用人"),c("inspector_name","验收人"),c("keeper_name","仓管人"),c("reviewer_name","审核人"),c("status_name","状态"));var lines=new Writer(book,"物料明细",c("order_no","单据编号"),c("sequence_no","行序号"),c("code","物料编码"),c("name","品名"),c("category_name","类别"),c("specification","规格型号"),c("batch_no","批次号"),c("gross_weight","毛重(g)"),c("impurity","杂质(g)"),c("net_weight","净重(g)"),c("quantity","数量"),c("purity","纯度(%)"),c("organization","单位名称"),c("receiving_organization","收货单位"),c("purpose","用途"),c("remark","备注"));long count=0,detailCount=0;
  for(int offset=0;;offset+=1000){var args=new ArrayList<>(p.args());args.add(offset);var rows=jdbc.queryForList("SELECT t.order_id,t.order_no,t.order_date,t.warehouse_name,t.type,t.operator_name,t.recipient_name,t.inspector_name,t.keeper_name,t.reviewer_name,t.status,f.factory_name,w.order_no work_order_no FROM metal_warehouse_order t LEFT JOIN metal_factory f ON f.factory_id=t.factory_id LEFT JOIN metal_work_order w ON w.work_order_id=t.work_order_id WHERE "+p.sql()+" ORDER BY t.order_id LIMIT 1000 OFFSET ?",args.toArray());for(var row:rows){row.put("type_name",TYPES.getOrDefault(Objects.toString(row.get("type")),""));row.put("status_name","VOID".equals(row.get("status"))?"已冲销":"已生效");summary.add(row);}if(!rows.isEmpty()){var ids=rows.stream().map(r->r.get("order_id")).toArray();String placeholders=String.join(",",Collections.nCopies(ids.length,"?"));jdbc.query("SELECT l.*,t.order_no FROM metal_warehouse_order_line l JOIN metal_warehouse_order t ON t.order_id=l.order_id WHERE l.order_id IN ("+placeholders+") ORDER BY l.order_id,l.sequence_no",(org.springframework.jdbc.core.RowCallbackHandler)rs->{Map<String,Object> row=new HashMap<>();var metadata=rs.getMetaData();for(int i=1;i<=metadata.getColumnCount();i++)row.put(metadata.getColumnLabel(i),rs.getObject(i));row.put("category_name",switch(Objects.toString(row.get("category"))){case "RAW"->"原材料";case "SEMI"->"半成品";default->"成品";});lines.add(row);},ids);}count+=rows.size();if(rows.size()<1000)break;}
  book.write(output);LoggerFactory.getLogger(getClass()).info("BUSINESS_EXPORT kind=warehouse-order count={} factory={}",count,q.getFactoryId());return count;}finally{book.dispose();}
 }
}
